def hkid_check(s):
    if len(s) == 7:
        s = ' ' + s
    total = 0
    for ch, w in zip(s, range(9, 1, -1)):
        if ch == ' ':
            v = 36
        elif ch.isalpha():
            v = ord(ch.upper()) - 55
        else:
            v = int(ch)
        total += v * w
    d = 11 - total % 11
    if d == 11:
        return '0'
    if d == 10:
        return 'A'
    return str(d)

def validate(name, sex, age, phone, email):
    errors = []
    if name.strip() == '':
        errors.append('presence')
    if sex not in ('M', 'F'):
        errors.append('fixed')
    if not age.isdigit():
        errors.append('type')
    elif int(age) <= 12:
        errors.append('range')
    if not (len(phone) == 8 and phone.isdigit()):
        errors.append('length')
    parts = email.split('@')
    if not (len(parts) == 2 and parts[0] and parts[1]):
        errors.append('format')
    return errors

