def bin_to_dec(s):
    total = 0
    for ch in s:
        total = total * 2 + int(ch)
    return total

def to_base(n, b):
    digits = '0123456789ABCDEF'
    if n == 0:
        return '0'
    out = ''
    while n > 0:
        out = digits[n % b] + out
        n //= b
    return out

